"use client";

import { useState } from "react";

export default function Navbar() {
  const [menuOpen, setMenuOpen] = useState(false);

  return (
    <>
      {/* MOBILE APP BANNER */}
      <div className="mobile-app-banner">
        <button className="app-close">×</button>

        <div className="app-logo">♧</div>

        <div className="app-text">
          <strong>Get the app</strong>
          <span>The fastest, easiest way to Airbnb</span>
        </div>

        <button className="use-app-button">
          USE APP
        </button>
      </div>

      <header className="navbar">
        <div className="navbar-inner">

          {/* LOGO */}
          <div className="logo">
            <span className="logo-symbol">♧</span>
            <span className="logo-text">airbnb</span>
          </div>

          {/* DESKTOP NAV */}
          <nav className="desktop-nav">

            <button className="nav-category active">
              <span className="nav-category-icon">🌍</span>
              <span>All</span>
            </button>

            <button className="nav-category">
              <span className="nav-category-icon">🏠</span>
              <span>Homes</span>
            </button>

            <button className="nav-category">
              <span className="nav-category-icon">🎈</span>
              <span>Experiences</span>
            </button>

            <button className="nav-category">
              <span className="nav-category-icon">🛎️</span>
              <span>Services</span>
            </button>

          </nav>

          {/* DESKTOP RIGHT */}
          <div className="navbar-right">

            <button className="host-link">
              Become a host
            </button>

            <button className="profile-avatar">
              P
            </button>

            <button
              className="menu-button"
              onClick={() => setMenuOpen((value) => !value)}
              aria-label="Open menu"
            >
              <span className="menu-lines">☰</span>
            </button>

          </div>

          {menuOpen && (
            <div className="profile-menu">

              <button>Sign up</button>

              <button>Log in</button>

              <div className="menu-divider" />

              <button>Become a host</button>

              <button>Help Center</button>

            </div>
          )}

        </div>
      </header>
    </>
  );
}